// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid huge values
        vm.assume(amount < 1e30);
        // Since the contract has no actual tokens, we need to assume it's not shutdown
        // and that the call won't revert due to allowance issues
        // The property is: the operator address remains unchanged after any depositAndStake call
        // For reference C: owner() returns the actual owner (address(this) in setUp), 
        // For mutant: owner() returns address(0)
        // We can test a property that holds for reference but fails for mutant:
        // Owner is not zero address after depositAndStake
        c.depositAndStake(amount);
        assertTrue(c.owner() != address(0));
    }
}

