contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= 1e24);
        // The operator is set to caller for this test
        // Actually, we just need to call depositAndStake, but it requires msg.sender == operator
        // The constructor sets operator = address(this) (the test contract)
        // So we need to prank as address(this) which is already the case, but we can also prank as a specific operator
