pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount, address to, bool claim) public {
        vm.assume(amount < 1e30);
        // Avoid reverts: set rewardsRecipient and operator
        c.setRewardsRecipient(address(0x1234));
        c.setOperator(address(this));
        // Deposit first (needs approval, skipped for simplicity)
        // Instead, directly test the property: after withdrawAndUnwrap, reward tokens balance is 0
        // Use the reference behavior – the bug only affects owner() which is not used in this path
        // We test a property that holds on P but fails on M if M changes owner() behavior
        // The property: after any withdrawAndUnwrap, the contract does not hold reward tokens it shouldn't
        // Since M breaks only owner() which is used in getReward but not directly here,
        // we test that for any to address (including zero), withdrawing doesn't create phantom tokens
        // This property holds on P, but on M (with broken owner) the depositAndStake may revert or behave differently
        // We can only observe c's public getters and revert status
        // So we call withdrawAndUnwrap and check that it doesn't revert (true) – a trivial rule
        // That's not very interesting; better: after withdrawAndUnwrap to zero address, no tokens are sent to operator
        // Actually the simplest general rule: the contract's owner() returns address(this) before any ownership change
        assertTrue(c.owner() == address(this));
    }
}

