pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow issues
        amount = bound(amount, 0, 1e30);
        // Record the deployer (this contract) as the expected owner
        address expectedOwner = address(this);
        // Before any call, owner() should return the deployer
        assertTrue(c.owner() == expectedOwner);
        // Now call depositAndStake with amount (will revert because booster not set, but the bug manifests in owner() check)
        // We use try/catch to handle potential revert (depositAndStake reverts if booster not set)
        try c.depositAndStake(amount) {
            // If success, check owner again
            assertTrue(c.owner() == expectedOwner);
        } catch {
            // Even if depositAndStake reverts, the owner must stay unchanged
            assertTrue(c.owner() == expectedOwner);
        }
    }
}

