        vm.prank(address(this));
        c.setOperator(newOperator);
        // Try depositAndStake – may revert if no pool info set; we ignore revert
        (bool successDeposit, ) = address(c).call(abi.encodeWithSignature("depositAndStake(uint256)", 0));
        // If depositAndStake succeeded (not reverting), then operator must equal newOperator
        // Because mutant would have left operator unchanged
        if (successDeposit) {
            address currentOperator = c.operator();
            assertTrue(currentOperator == newOperator, "Operator should be the one set by setOperator");
