        try c.depositAndStake(amount) {
            success = true;
        } catch {
            // depositAndStake reverted, skip this fuzz case
        }

        if (success) {
            // Assert that rewardsRecipient is unchanged
            assertTrue(c.rewardsRecipient() == initialRecipient, "rewardsRecipient changed after depositAndStake");
        }
    }
