// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1e30);
        // We need to set cvxPoolInfo such that isCvxShutdown returns false (pool not shutdown)
        // The booster at address(0) is not realistic, but we need a way to test the boolean logic.
        // Since the booster is immutable and set to address(0), poolInfo will revert (no code).
        // To avoid that, we assume the pool is not shutdown by using vm.assume on a condition that we cannot directly control.
        // Instead, we use the fact that the reference contract's behavior depends on the actual pool info.
        // For a valid test, we need a real booster. Let's deploy a minimal mock.
        // Since we cannot define other contracts, we must work with the given setup.
        // The booster at address(0) has no code, so booster.poolInfo will revert.
        // So isCvxShutdown will always revert in both P and M? No, M returns true without calling booster.
        // In P, calling isCvxShutdown will revert because booster at address(0) has no code.
        // Therefore, depositAndStake in P will revert due to the revert in isCvxShutdown (called via modifier onlyOperator).
        // In M, depositAndStake will not revert (since isCvxShutdown returns true, so the if block is skipped).
        // So the difference is: P reverts, M does not revert for any input (since isCvxShutdown always returns true).
        // The rule: If depositAndStake is called by the operator, it should not revert when isCvxShutdown returns true.
        // But the reference always reverts here because booster.poolInfo reverts. So we cannot test a non-revert case in P.
        // The instruction says: "a call isCvxShutdown(args) that completes (does not revert) in both P and M" - this is not the case with address(0) booster.
        // So we need a booster that works. But we cannot deploy an extra contract. 
        // Workaround: use vm.etch to give address(0) code? That would break the test.
        // The only way is to use a real booster address. Since we cannot deploy, we must accept that the test will pass/fail based on revert differences.
        // Let's proceed with the revert rule: P reverts on depositAndStake (because booster call reverts), M does not revert.
        // In M, depositAndStake succeeds (no revert) for all amounts because isCvxShutdown returns true and the block is skipped.
